import ts from 'typescript';
import {readFileSync} from 'node:fs';
const path='packages/pal-extract/src/font/bdf-to-json.ts';
const js=ts.transpileModule(readFileSync(path,'utf8'),{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;
const {parseBdf}=await import('data:text/javascript;base64,'+Buffer.from(js).toString('base64'));
const observations=['F','1G','GG'].map(row=>({row,bitmap:[...parseBdf(['STARTCHAR A','ENCODING 65','BBX 16 1 0 0','BITMAP',row,'ENDCHAR'].join('\n'))[0].bitmap]}));
if(JSON.stringify(observations.map(x=>x.bitmap))!==JSON.stringify([[15,0],[1,0],[0,0]]))process.exitCode=1;
process.stdout.write(JSON.stringify({observations,scope:'Actual parseBdf; malformed/short-row comment counter only; no behavior change or new accepted input contract.'})+'\n');

